describe('Timezone Setting in Profile Settings', () => {
  beforeEach(() => {
    cy.visit('/profile/settings');
  });

  it('should successfully set timezone in profile settings', () => {
    // Verify timezone dropdown is visible and has default value
    cy.get('[data-testid="timezone-select"]').should('be.visible');
    cy.get('[data-testid="timezone-select"]').should('have.value', 'America/New_York');

    // Select a new timezone from the dropdown
    cy.get('[data-testid="timezone-select"]').select('Europe/London');

    // Verify the selected value is displayed
    cy.get('[data-testid="timezone-display"]').should('contain', 'Europe/London');

    // Click save button
    cy.get('[data-testid="save-profile-btn"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Timezone updated successfully');

    // Verify timezone is persisted after refresh
    cy.reload();
    cy.get('[data-testid="timezone-select"]').should('have.value', 'Europe/London');
  });

  it('should handle invalid timezone selection and prevent save', () => {
    // Verify timezone dropdown is visible
    cy.get('[data-testid="timezone-select"]').should('be.visible');

    // Attempt to select an invalid timezone (e.g., empty string or non-existent option)
    cy.get('[data-testid="timezone-select"]').select('Invalid/Timezone');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please select a valid timezone');

    // Verify save button is disabled or does not submit
    cy.get('[data-testid="save-profile-btn"]').should('be.disabled');

    // Attempt to click save button
    cy.get('[data-testid="save-profile-btn"]').click();

    // Verify error message persists
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify timezone was not updated
    cy.get('[data-testid="timezone-display"]').should('contain', 'America/New_York');
  });
});
